def forward(groups):
    epoch, sp1, task_id = groups
    return {'stored': [int(epoch) * 1000000], 'layout': [len(sp1), int(task_id)]}

def inverse(record):
    micros = record['stored'][0]
    sp1_len = record['layout'][0]
    task_id = record['layout'][1]
    epoch = str(micros // 1000000)
    return epoch + (' ' * sp1_len) + str(task_id)

